# Never mutate live sources. Save guarded before/proposal carriers and a unified diff.
entries=[]
for i in ids:
 before=original[i];after=texts[i]
 assert before!=after,i
 assert before.split('---',2)[1]==after.split('---',2)[1],i
 (base/'before'/f'{i}.md').write_text(before)
 (base/'proposed'/f'{i}.md').write_text(after)
 diff=''.join(difflib.unified_diff(before.splitlines(True),after.splitlines(True),fromfile=f'items/{i}.md',tofile=f'items/{i}.md'))
 (base/f'{i}.diff').write_text(diff)
 entries.append({'id':i,'live_path':f'items/{i}.md','before':str(base/'before'/f'{i}.md'),'proposed':str(base/'proposed'/f'{i}.md'),'before_raw_sha256':hashlib.sha256(before.encode()).hexdigest(),'proposed_raw_sha256':hashlib.sha256(after.encode()).hexdigest(),'diff':str(base/f'{i}.diff'),'frontmatter_unchanged':True})
(base/'proposal-manifest.json').write_text(json.dumps({'run':'fluid-dynamics-all-47-2026-10-23','outside_cycle':1,'native_review':False,'native_adjudication':False,'draft_only':True,'entries':entries},indent=2)+'\n')
print('Wrote',len(entries),'draft-only proposals under',base)
